screens={'military':['MilitaryPanel','BattleSiegePanel','ArmyDock'],'economy':['ConstructionPanel','ResourceTradePanel','ProductionPanel','GamePanel'],'technology':['TechnologyTreePanel'],'focuses':['NationalFocusPanel','PoliticalDecisionsPanel'],'diplomacy':['DiplomacyPanel','PeaceNegotiations','EspionagePanel'],'events':['NotificationFeed','WorldStatistics','QuickTutorial','LoadingScreen'],'government':['GamePanel','StrategyCouncil','PoliticalDecisionsPanel']}
layout=[subjects['military'][:10],subjects['military'][10:],subjects['economy'][:10],subjects['economy'][10:]+subjects['government'][:2],subjects['technology'][:10],subjects['technology'][10:]+subjects['focuses'][:5],subjects['focuses'][5:],subjects['diplomacy'][:10],subjects['diplomacy'][10:]+subjects['events'][:8],subjects['events'][8:]+subjects['government'][2:]]
source_map=json.loads((OUT/'generation-sources.json').read_text());source_dir=Path(sys.argv[1]);manifest=[]
for sheet,rows in enumerate(layout,1):
    path=source_dir/source_map[str(sheet)];image=Image.open(path).convert('RGB');a=np.asarray(image).astype(float);height,width=a.shape[:2]
    # The generator may make tiny unequal grid boundaries. Use actual straight seams.
    vertical=np.abs(a[1:]-a[:-1]).mean(axis=(1,2));seams=[]
    for y in np.argsort(vertical)[::-1]:
        if height*.1<y<height*.9 and all(abs(y-old)>height*.12 for old in seams):seams.append(int(y)+1)
        if len(seams)==4:break
    assert len(seams)==4,'Four actual painting row seams required'
    cuts=[0,*sorted(seams),height]
    for panel,(id,title,era,description) in enumerate(rows):
        category=next(c for c,items in subjects.items() if any(row[0]==id for row in items));row,col=divmod(panel,2);top,bottom=cuts[row],cuts[row+1]
        horizontal=np.abs(a[top:bottom,1:]-a[top:bottom,:-1]).mean(axis=(0,2));lo=int(width*.4);hi=int(width*.6);middle=int(lo+np.argmax(horizontal[lo:hi]))+1
        left,right=(0,middle) if col==0 else (middle,width);rect=(left+1,top+1,right-1,bottom-1);painting=image.crop(rect);painting.thumbnail((640,384),Image.Resampling.LANCZOS)
        relative=category+'/'+id+'.webp';target=OUT/relative;target.parent.mkdir(exist_ok=True);painting.save(target,'WEBP',quality=85,method=6)
        manifest.append({'id':id,'filename':relative,'titleRu':title,'description':description,'category':category,'era':era,'purpose':'Illustrates the corresponding real Dominion system; historical flavor, not a new mechanic','screens':screens[category],'width':painting.width,'height':painting.height,'bytes':target.stat().st_size,'sha256':hashlib.sha256(target.read_bytes()).hexdigest(),'origin':{'generator':'OpenAI image_gen','sourceSheet':path.name,'sourceSha256':hashlib.sha256(path.read_bytes()).hexdigest(),'panel':panel+1,'cropRect':rect},'rights':'Original AI-assisted project artwork generated for Dominion; use permitted under applicable OpenAI terms; no third-party game assets'})
assert len(manifest)==100 and len({e['sha256'] for e in manifest})==100
assert Counter(e['category'] for e in manifest)==Counter(military=20,economy=18,technology=15,focuses=15,diplomacy=12,events=10,government=10)
(OUT/'art-manifest.json').write_text(json.dumps(manifest,ensure_ascii=False,indent=2)+'\n')
registry="/** Static Metro references; images decode only in mounted panels. Generated by prepare-art211.py. */\nexport const ART_211={\n"+'\n'.join(" '"+e['id']+"':require('../../assets/art/dominion-2.1.1/"+e['filename']+"')," for e in manifest)+"\n} as const;\nexport type IllustrationId=keyof typeof ART_211;\n"
(ROOT/'src/art/library.ts').write_text(registry)
print('PASS:',len(manifest),'distinct paintings,',sum(e['bytes'] for e in manifest),'optimized bytes')
